import {React} from "react";
import {useStateMachine} from "little-state-machine";
import {Link, useParams} from "react-router-dom";
import {useForm} from 'react-hook-form';
import {useNavigate} from 'react-router-dom';
import {CITY_LIST, generateSurveyID} from '../core/generateSurvey';
import './theme.css';
import './SurveyCitySelectPage.css';
import {DEFAULT_LANG, locale_text} from "./lang";


const SubmitButton = (opts) => {
    return (
        <button className="button-generic button-stick-to-right button-survey-select-submit" {...opts}></button>
    )
};

const RadioForm = ({options}) => {
    let navigate = useNavigate();

    const {
        register,
        handleSubmit,
        watch,
        formState: {isDirty, isValid}
    } = useForm();

    const onSubmit = (data) => {
        // TODO: Replace this with the actual survey ID.
        const city = data.options;
        const surveyID = generateSurveyID(city);
        // console.log('Selected option:', data.options);
        navigate(`/survey/${surveyID}`);
    };

    return (
        <form onSubmit={handleSubmit(onSubmit)}>
            <div className="survey-city-select-grid-container">
                {options.map((option, index) => (
                    <div className="div-option-item">
                        <input
                            type="radio"
                            key={index}
                            id={option.value}
                            value={option.value}
                            {...register('options')}
                        />
                        <label htmlFor={option.value}>
                            {option.label}
                        </label>
                    </div>
                ))}
            </div>


            <SubmitButton disabled={!isDirty || !isValid}>
                {locale_text(options['lang'], 'survey-img-choice-submit-button')}
            </SubmitButton>
        </form>
    );
};


export function SurveyCitySelectPage() {

    const {state} = useStateMachine();
    const lang = state['language'] || DEFAULT_LANG;

    // Send a request to /api/hello, and print the response to the console.
    // fetch('/api/hello')
    //     .then(response => response.json())
    //     .then(data => console.log(data));

    const cities = CITY_LIST;

    let options = cities.map(
        // TODO: city should be translated to the user's language.
        (city) => ({value: city, label: locale_text(lang, `city-list-${city}`)})
    );
    options['lang'] = lang;


    return (
        <div className="container-page-mid-root">
            <h1 className="title-text city-select-title-text-h1">
                {locale_text(lang, 'survey-city-select-title')}
            </h1>
            <div className="container-after-one-digit">
                <p className="description-text">
                    {locale_text(lang, 'survey-city-select-description')}
                </p>

                <RadioForm options={options}/>
            </div>
        </div>
    );
}
